const labels={pending:'Pending review',changes:'Changes requested',approved:'Approved',rejected:'Rejected'};
let drivers=readStored(),selected=null,activeDoc=null,currentView='pending';
function readStored(){try{return JSON.parse(localStorage.getItem('routecrewApplications'))||[]}catch{return[]}}
function persist(){localStorage.setItem('routecrewApplications',JSON.stringify(drivers))}
function initials(name=''){return name.split(/\s+/).filter(Boolean).map(v=>v[0]).slice(0,2).join('').toUpperCase()||'DR'}
function timeLabel(value){if(!value)return '—';const [h,m]=value.split(':').map(Number);return `${h%12||12}:${String(m).padStart(2,'0')} ${h>=12?'PM':'AM'}`}
function sizeLabel(bytes=0){return bytes>=1048576?`${(bytes/1048576).toFixed(1)} MB`:`${Math.max(0,Math.round(bytes/1024))} KB`}
function safe(value,fallback='—'){return value===undefined||value===null||value===''?fallback:String(value)}
function setText(id,value,fallback='—'){const el=document.querySelector('#'+id);if(el)el.textContent=safe(value,fallback)}
function normalizedShifts(driver){
  if(driver.shifts)return driver.shifts;
  return {pickup:driver.morningTime?{enabled:true,start:driver.morningTime,end:null}:{enabled:false},drop:driver.eveningTime?{enabled:true,start:driver.eveningTime,end:null}:{enabled:false}};
}
function normalizedEngagements(driver){if(Array.isArray(driver.engagements))return driver.engagements;if(driver.engagement)return [driver.engagement];return []}
function filteredDrivers(){const term=(document.querySelector('#searchDrivers').value||'').toLowerCase();const status=document.querySelector('#statusFilter').value;return drivers.filter(d=>{const viewMatch=currentView==='audit'||(currentView==='pending'?(d.status==='pending'||d.status==='rejected'):d.status===currentView);const statusMatch=status==='all'||d.status===status;return viewMatch&&statusMatch&&`${d.name||''} ${d.phone||''} ${d.vehicle||''} ${d.licenceNumber||''} ${d.company||''} ${d.id||''}`.toLowerCase().includes(term)})}
function renderQueue(){const shown=filteredDrivers();document.querySelector('#queueCount').textContent=`${shown.length} result${shown.length===1?'':'s'}`;document.querySelector('#driverQueue').innerHTML=shown.map(d=>`<button class="queue-item ${selected&&d.id===selected.id?'selected':''}" data-id="${d.id}"><span class="queue-avatar">${initials(d.name)}</span><span class="queue-copy"><strong>${safe(d.name,'Unnamed driver')}</strong><span>${safe(d.vehicle,'Vehicle not provided')}</span><small>${currentView==='audit'?(d.audit?.at(-1)?.action||labels[d.status]||'Updated'):(labels[d.status]||'Unknown')}</small></span><span class="queue-age">${d.submittedAt?new Date(d.submittedAt).toLocaleDateString():'—'}</span></button>`).join('')||'<p style="padding:20px;color:#718078">No applications in this section.</p>';document.querySelectorAll('.queue-item').forEach(b=>b.onclick=()=>selectDriver(b.dataset.id));const pending=drivers.filter(d=>d.status==='pending').length;document.querySelector('#pendingCount').textContent=`${pending} application${pending===1?'':'s'}`;document.querySelector('#navCount').textContent=pending;if(selected&&!shown.some(d=>d.id===selected.id))clearSelection()}
function clearSelection(){selected=null;document.querySelector('#reviewPanel').classList.add('empty')}
function formatShift(shift){if(!shift||shift.enabled===false)return 'Not available';if(shift.start&&shift.end)return `${timeLabel(shift.start)} – ${timeLabel(shift.end)}`;if(shift.start)return `From ${timeLabel(shift.start)}`;return 'Available'}
function formatHomeLocation(driver){const home=driver.homeLocation||{};return home.lat&&home.lng?`${home.lat}, ${home.lng}`:'Not captured'}
function selectDriver(id){
  selected=drivers.find(d=>d.id===id);if(!selected)return;
  document.querySelector('#reviewPanel').classList.remove('empty');
  const docs=selected.documents||[],rc=docs.find(d=>d.type==='Vehicle RC'),insurance=docs.find(d=>d.type==='Vehicle insurance'),shifts=normalizedShifts(selected),engagements=normalizedEngagements(selected),home=selected.homeLocation||{};
  setText('driverName',selected.name,'Driver');setText('driverAvatar',initials(selected.name));setText('driverInfo',`${safe(selected.id)} · ${safe(selected.phone)} · ${safe(selected.vehicle,'Vehicle not provided')}`);
  setText('driverDob',selected.dob);setText('licenceNumberDisplay',selected.licenceNumber,'Not provided');setText('experienceYears',selected.experience?`${selected.experience} years`:'—');setText('referralDisplay',selected.referralCode||'Not referred');
  setText('homeAddressDisplay',home.address||selected.address||'Not provided');setText('homeLocationDisplay',formatHomeLocation(selected));setText('homeLocationSourceDisplay',home.source==='device'?'Device geolocation':home.source==='manual'?'Manual address':'Not provided');
  setText('vehicleOwnershipDisplay',selected.vehicleOwnership==='own'?'Own vehicle':selected.vehicleOwnership==='company'?'Company / vendor assigned':'Not provided');setText('companyName',selected.vehicleOwnership==='company'?(selected.company||'Not provided'):'Not applicable');setText('vehicleRegistrationDisplay',selected.vehicle);setText('vehicleType',selected.type);setText('vehicleModelDisplay',[selected.vehicleMake,selected.vehicleModel,selected.vehicleYear].filter(Boolean).join(' · ')||'—');setText('fuelTypeDisplay',selected.fuelType);setText('capacityDisplay',selected.capacity?`${selected.capacity} passengers`:'—');setText('insuranceExpiryDisplay',selected.insuranceExpiry?new Date(`${selected.insuranceExpiry}T00:00:00`).toLocaleDateString():'—');setText('rcBookDisplay',rc?`${rc.file} · ${rc.state==='verified'?'Verified':'Review required'}`:'Missing');setText('insuranceDocumentDisplay',insurance?`${insurance.file} · ${insurance.state==='verified'?'Verified':'Review required'}`:'Missing');
  setText('pickupAvailabilityDisplay',formatShift(shifts.pickup));setText('dropAvailabilityDisplay',formatShift(shifts.drop));setText('extraTripsDisplay',selected.acceptsExtraTrips?'Interested':'Not interested');
  renderEngagements(engagements);renderConsent(selected.consent||{});
  const badge=document.querySelector('#driverStatus');badge.textContent=labels[selected.status]||'Unknown';badge.className=`badge ${selected.status||'pending'}`;document.querySelector('#reviewNote').value=selected.reviewNote||'';
  updateChecks({docs,shifts,engagements,home});renderDocuments();renderQueue();
}
function renderEngagements(items){const box=document.querySelector('#engagementDisplay');document.querySelector('#engagementCount').textContent=String(items.length);if(!items.length){box.innerHTML='<p>No existing company or vendor engagement declared.</p>';return}box.innerHTML=items.map((e,i)=>{const org=[e.vendor,e.company].filter(Boolean).join(' / ')||'Organization not provided';const window=e.start||e.end?`${timeLabel(e.start)} – ${timeLabel(e.end)}`:'Time not provided';const days=Array.isArray(e.days)&&e.days.length?e.days.map(d=>['Sun','Mon','Tue','Wed','Thu','Fri','Sat'][d]||d).join(', '):'Days not provided';return `<div class="engagement-item"><b>${i+1}. ${org}</b><span>${safe(e.location,'Location not provided')}</span><small>${days} · ${window}</small></div>`}).join('')}
function renderConsent(consent){const map=[['verificationConsentState',consent.verification],['locationConsentState',consent.onDutyLocation],['declarationConsentState',consent.declaration]];map.forEach(([id,ok])=>{const el=document.querySelector('#'+id);el.textContent=ok?'✓':'!';el.classList.toggle('ok',!!ok);el.classList.toggle('missing',!ok)})}
function updateChecks({docs,shifts,home}){const hasRc=docs.some(d=>d.type==='Vehicle RC'),hasInsurance=docs.some(d=>d.type==='Vehicle insurance'),hasLicence=docs.some(d=>d.type==='Driving licence');document.querySelector('#vehicleCheck').textContent=selected.vehicle&&selected.vehicleMake&&selected.vehicleModel&&selected.capacity&&selected.fuelType&&selected.insuranceExpiry&&hasRc&&hasInsurance?'Ready to verify':'Details or documents incomplete';document.querySelector('#identityCheck').textContent=selected.name&&selected.dob&&selected.licenceNumber&&hasLicence&&(home.address||selected.address||home.lat)?'Ready to verify':'Details incomplete';document.querySelector('#availabilityCheck').textContent=(shifts.pickup?.enabled||shifts.drop?.enabled)?'Captured':'No pickup/drop availability'}
function renderDocuments(){const list=selected.documents||[],verified=list.filter(d=>d.state==='verified').length,required=['Driving licence','Aadhaar card','Vehicle RC','Vehicle insurance','Driver photograph'],missing=required.filter(type=>!list.some(d=>d.type===type)),requiredVerified=required.every(type=>list.some(d=>d.type===type&&d.state==='verified'));document.querySelector('#verifiedProgress').textContent=missing.length?`Missing: ${missing.join(', ')}`:`${verified} of ${list.length} verified`;document.querySelector('#approveProfile').disabled=!requiredVerified;document.querySelector('#documentList').innerHTML=list.map((d,i)=>`<div class="document-row"><span class="doc-icon">▤</span><span class="doc-copy"><b>${d.type}</b><small>${d.file} · ${sizeLabel(d.size)}</small></span><span class="doc-state ${d.state}">${d.state==='verified'?'Verified':d.state==='reupload'?'Re-upload needed':'Awaiting review'}</span><button class="view-doc" data-doc="${i}">Open</button></div>`).join('')||'<p style="padding:16px;color:#718078">No document metadata was submitted.</p>';document.querySelectorAll('.view-doc').forEach(b=>b.onclick=()=>openDocument(+b.dataset.doc))}
function audit(action){selected.audit=selected.audit||[];selected.audit.push({action,at:new Date().toISOString()})}
function setDocState(state){selected.documents[activeDoc].state=state;audit(`${selected.documents[activeDoc].type}: ${state==='verified'?'verified':'re-upload requested'}`);persist();document.querySelector('#documentModal').close();renderDocuments();notify(state==='verified'?'Document marked as verified.':'Re-upload requested.')}
function decide(status){const note=document.querySelector('#reviewNote').value.trim();if((status==='rejected'||status==='changes')&&!note){notify('Add a note explaining this decision.');document.querySelector('#reviewNote').focus();return}selected.status=status;selected.reviewNote=note;audit(labels[status]);persist();renderQueue();selectDriver(selected.id);notify(status==='approved'?'Driver approved.':status==='rejected'?'Driver profile rejected.':'Changes requested from driver.')}
function changeView(view){currentView=view;document.querySelectorAll('.admin-nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));const titles={pending:['Pending verification','Review submitted driver details and documents before activation.'],approved:['Verified drivers','Drivers approved by an authorized verifier.'],changes:['Re-upload requests','Applications waiting for corrected documents.'],audit:['Audit history','Review recorded submission and verification actions.']};document.querySelector('#viewTitle').textContent=titles[view][0];document.querySelector('#viewDescription').textContent=titles[view][1];document.querySelector('#statusFilter').value='all';clearSelection();renderQueue()}
function notify(message){const toast=document.querySelector('#toast');toast.textContent=message;toast.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>toast.classList.remove('show'),2600)}
document.querySelector('#searchDrivers').oninput=renderQueue;document.querySelector('#statusFilter').onchange=renderQueue;document.querySelectorAll('.admin-nav button').forEach(b=>b.onclick=()=>changeView(b.dataset.view));document.querySelector('#closeModal').onclick=()=>document.querySelector('#documentModal').close();document.querySelector('#modalVerify').onclick=()=>setDocState('verified');document.querySelector('#modalReupload').onclick=()=>setDocState('reupload');document.querySelector('#approveProfile').onclick=()=>decide('approved');document.querySelector('#rejectProfile').onclick=()=>decide('rejected');document.querySelector('#requestChanges').onclick=()=>decide('changes');renderQueue();if(filteredDrivers()[0])selectDriver(filteredDrivers()[0].id);
